CREATE TABLE CORE_OCTOPUS.T_DIM_SUPPLIER_SITE_2 (
   supplier_site_sid                   NUMBER          NOT NULL COMMENT 'Supplier_2 site where the goods are provided, for KoL (Komplettladung / Direktlogistik) logistic types',
   supplier_sid                        NUMBER          NOT NULL COMMENT 'Unique identifier for the supplier_2',
   country_cd                          VARCHAR(2)      COMMENT 'The code for the country_2 in which the site (cross docks) resides in.',
   country_descr                       VARCHAR(100)    COMMENT 'A textual description for country_cd written out in group language (German).',
   supplier_site_nr                    VARCHAR(20)     COMMENT 'The number which identifies the   in ',
   supplier_site_abbr_name             VARCHAR(100)    COMMENT 'The abbreviated name of the supplier_2',
   supplier_site_name                  VARCHAR(100)    COMMENT 'The name by which a site is known which is run by a supplier. ',
   supplier_site_transpoint_type_cd    VARCHAR(20)     COMMENT 'The type of the supplier_2 e.g. (PROD = Produktionsstätte, HEAD = Firmensitz, LOAD = Verladestandort)',
   supplier_site_transpoint_type_descr VARCHAR(100)    COMMENT 'The german description for the supplier_site_transpoint_type_cd',
   longitude                           NUMBER(9, 6)    COMMENT 'Object.address_2-data.coordinates x',
   latitude                            NUMBER(9, 6)    COMMENT 'Object.address_2-data.coordinates y',
   city_name                           VARCHAR(100)    COMMENT 'Name of the city',
   zip                                 VARCHAR(15)     COMMENT 'Zip code / PLZ',
   street_name                         VARCHAR(100)    COMMENT 'Name of the street',
   gln_nr                              VARCHAR(13)     COMMENT 'The Global Location_2 Number where the supplier_2 is located.',
   dwh_created_tmsp                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   dwh_updated_tmsp                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',   
   CONSTRAINT PK_T_DIM_SUPPLIER_SITE PRIMARY KEY (supplier_site_sid) NOT ENFORCED 
)  COMMENT = 'This entity contains sites which are operated by supplier_2, such as factories or distribution warehouses. ';
